namespace sitesplat\bblc_online;
class bblivechat { static $loaded = true; public function __construct() { \sitesplat\add_filter('bblc_handle_acp_settings', [$this, 'online_handle'], 1); \sitesplat\add_filter('bblc_display_acp_settings', [$this, 'online_form'], 99); } public function online_handle($error) { global $config, $request; $settings = $request->variable('bblc_online', ['' => 0]); $config->set('bblc_online', json_encode($settings)); return $error; } public function online_form($html) { global $config, $user; $settings = json_decode($config['bblc_online'], true); $msgcnt0 = ($settings['msgcnt'] == 0) ? ' checked' : ''; $msgcnt1 = ($settings['msgcnt'] == 1) ? ' checked' : ''; $onlist0 = ($settings['onlist'] == 0) ? ' checked' : ''; $onlist1 = ($settings['onlist'] == 1) ? ' checked' : ''; $onlist2 = ($settings['onlist'] == 2) ? ' checked' : ''; $onlfmt0 = ($settings['onlfmt'] == 0) ? ' checked' : ''; $onlfmt1 = ($settings['onlfmt'] == 1) ? ' checked' : ''; $onlfmt2 = ($settings['onlfmt'] == 2) ? ' checked' : ''; return $html . <<<EOT
<dl> <dt><label>{$user->lang['OL_MCNT']}{$user->lang['COLON']}</label><span>{$user->lang['OL_MCNT_EXPLAIN']}</span></dt> <dd> <label><input type="radio" class="radio" name="bblc_online[msgcnt]" value="0"$msgcnt0 /> {$user->lang['NO']}</label> <label><input type="radio" class="radio" name="bblc_online[msgcnt]" value="1"$msgcnt1 /> {$user->lang['YES']}</label> </dd> </dl> <dl> <dt><label>{$user->lang['OL_OLST']}{$user->lang['COLON']}</label><span>{$user->lang['OL_OLST_EXPLAIN']}</span></dt> <dd> <label><input type="radio" class="radio" name="bblc_online[onlist]" value="0"$onlist0 /> {$user->lang['NO']}</label> <label><input type="radio" class="radio" name="bblc_online[onlist]" value="1"$onlist1 /> {$user->lang['OL_NUSERS']}</label> <label><input type="radio" class="radio" name="bblc_online[onlist]" value="2"$onlist2 /> {$user->lang['OL_NULIST']}</label> </dd> </dl> <dl> <dt><label>{$user->lang['OL_LFMT']}{$user->lang['COLON']}</label><span>{$user->lang['OL_LFMT_EXPLAIN']}</span></dt> <dd> <label><input type="radio" class="radio" name="bblc_online[onlfmt]" value="0"$onlfmt0 /> {$user->lang['USERNAME']}</label> <label><input type="radio" class="radio" name="bblc_online[onlfmt]" value="1"$onlfmt1 /> {$user->lang['ACP_USER_AVATAR']}</label> <label><input type="radio" class="radio" name="bblc_online[onlfmt]" value="2"$onlfmt2 /> {$user->lang['OL_BOTH']}</label> </dd> </dl> <hr />
EOT;
} public static function online_list($chatcount, $chat_ary) { global $db, $config, $user, $language, $template; $chatlist = ''; $settings = json_decode($config['bblc_online'], true); if ($settings['msgcnt'] || $settings['onlist']) { $chktime = time() - 86400; $result = $db->sql_query("SELECT COUNT(*) AS mcnt FROM bblc_messages WHERE channel < 50000000 AND UNIX_TIMESTAMP(`dateTime`) > $chktime"); $mcnt = (int) $db->sql_fetchfield('mcnt'); $db->sql_freeresult($result); $href = append_sid(generate_board_url() . '/memberlist.php', 'mode=viewprofile'); if ($settings['onlist'] == 2) { foreach ($chat_ary as $chatter) { $chatuser = $chatter[1]; if ($settings['onlfmt'] == 2) { $chatuser .= $chatter[0]; } else if ($settings['onlfmt'] == 0) { $chatuser = $chatter[0]; } $chatlist .= '<a href="' . $href . '&amp;u=' . $chatter[2] . '">' . "{$chatuser}</a>"; } } } $template->assign_vars([ 'S_BBLC_ONLINE' => $settings['msgcnt'] || $settings['onlist'], 'BBLC_MSGCNT' => ($settings['msgcnt']) ? sprintf("$mcnt") : '', 'BBLC_ONLIST' => ($settings['onlist']) ? sprintf("$chatcount") : '', 'BBLC_ONLFMT' => $chatlist, ]); } }